package com.example.causal.testsupport;

import org.neo4j.graphdb.GraphDatabaseService;
import org.neo4j.graphdb.Result;
import org.neo4j.graphdb.Transaction;

/**
 * Helper to load synthetic data generated by dev/synthetic.py into an embedded Neo4j test database.
 * The Neo4j test harness must be configured with a working directory pointing to the dev folder
 * so that LOAD CSV can locate the files.
 */
public final class SyntheticDataSupport {

    private SyntheticDataSupport() {}

    /**
     * Wipes the database and loads the nodes and edges for the specified config and sample size.
     */
    public static void load(GraphDatabaseService db, int configId, String sampleSize) {
        clear(db);

        String nodesFileName = String.format("/causal_nodes%d_%s.csv", configId, sampleSize);
        String edgesFileName = String.format("/causal_edges%d_%s.csv", configId, sampleSize);

        java.net.URL nodesResource = SyntheticDataSupport.class.getResource(nodesFileName);
        java.net.URL edgesResource = SyntheticDataSupport.class.getResource(edgesFileName);

        if (nodesResource == null || edgesResource == null) {
            throw new IllegalStateException("CSV files not found on classpath. Ensure pom.xml includes them.");
        }

        String nodesUrl = nodesResource.toString();
        String edgesUrl = edgesResource.toString();

        try (Transaction tx = db.beginTx()) {
            // 1. Load Nodes
            String loadNodesCypher = String.format(
                    "LOAD CSV WITH HEADERS FROM '%s' AS row " +
                    "CREATE (n:Variable) " +
                    "SET n.id = row.nodeId, n.name = row.name, n.label = row.label", nodesUrl);
            tx.execute(loadNodesCypher);

            // 2. Load Edges
            String loadEdgesCypher = String.format(
                    "LOAD CSV WITH HEADERS FROM '%s' AS row " +
                    "MATCH (source:Variable {id: row.source}) " +
                    "MATCH (target:Variable {id: row.target}) " +
                    "CREATE (source)-[:CAUSES]->(target)", edgesUrl);
            tx.execute(loadEdgesCypher);

            tx.commit();
        }
    }

    /**
     * Clears all nodes and relationships from the database.
     */
    public static void clear(GraphDatabaseService db) {
        try (Transaction tx = db.beginTx()) {
            tx.execute("MATCH (n) DETACH DELETE n");
            tx.commit();
        }
    }

    /**
     * Returns [nodeCount, edgeCount] after loading to verify the ingest.
     */
    public static long[] graphCounts(GraphDatabaseService db) {
        try (Transaction tx = db.beginTx()) {
            Result r = tx.execute(
                "MATCH (v:Variable) WITH count(v) AS nodes " +
                "MATCH ()-[r:CAUSES]->() WITH nodes, count(r) AS edges " +
                "RETURN nodes, edges");
            var row = r.next();
            return new long[] {
                (long) row.get("nodes"),
                (long) row.get("edges")
            };
        }
    }
}
